namespace NavisWorld.Cosmos;
public readonly record struct SynapticFeature(double BaselineDelta,double Quality);public readonly record struct SynapticUpdate(double[] Vector,long Revision,double Confidence);
public sealed class SynapseState{public const double PhaseStep=0.61803398875;private readonly double _leak,_inputGain;private double[] _vector;public long Revision{get;private set;}public SynapseState(int dimensions=12,double leak=0.88,double inputGain=0.12){if(dimensions<=0)throw new ArgumentOutOfRangeException(nameof(dimensions));if(!double.IsFinite(leak)||leak<0||leak>=1)throw new ArgumentOutOfRangeException(nameof(leak));if(!double.IsFinite(inputGain)||inputGain<0)throw new ArgumentOutOfRangeException(nameof(inputGain));_leak=leak;_inputGain=inputGain;_vector=new double[dimensions];}public SynapticUpdate Update(IReadOnlyList<SynapticFeature> features,double confidence=1){if(!double.IsFinite(confidence)||confidence<0||confidence>1)throw new ArgumentOutOfRangeException(nameof(confidence));foreach(var f in features)if(!double.IsFinite(f.BaselineDelta)||!double.IsFinite(f.Quality)||f.Quality<0||f.Quality>1)throw new ArgumentException("invalid feature",nameof(features));Revision++;if(features.Count==0)return new SynapticUpdate((double[])_vector.Clone(),Revision,0);var inputs=features.Select(f=>Math.Tanh(f.BaselineDelta)*f.Quality).ToArray();var next=new double[_vector.Length];for(var i=0;i<next.Length;i++){var phase=Math.Sin((i+1)*PhaseStep);var value=_leak*_vector[i]+_inputGain*inputs[i%inputs.Length]*phase;next[i]=Math.Clamp(value,-1,1);}_vector=next;return new SynapticUpdate((double[])next.Clone(),Revision,confidence);}}
